type Args<T extends (...args: any) => any> = T extends (...args: infer P) => any ? P : never;
declare function f({x}: {x: number}, [y]: [string], z?: boolean): void;
type Result = Args<typeof f>;

type Args<T extends (...args: any) => any> = T extends (...args: infer P) => any ? P : never;
declare function f(...[first, ...tail]: [number, ...string[]]): void;
type Result = Args<typeof f>;

type Args<T extends (...args: any) => any> = T extends (...args: infer P) => any ? P : never;
declare function f(first: number, second?: string): void;
type Result = Args<typeof f>;
